<?php
require_once __DIR__.'/../includes/config.php';
requireLogin();
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCSRFToken($_POST['csrf_token']??null))$error='Invalid session token.';
 else{
  $current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';
  $row=safeRun($pdo,'SELECT password FROM users WHERE id=?',[$_SESSION['user_id']])->fetch();
  if(!$row||!password_verify($current,$row['password']))$error='Current password is incorrect.';
  elseif(strlen($new)<10||!preg_match('/[A-Z]/',$new)||!preg_match('/[a-z]/',$new)||!preg_match('/\d/',$new))$error='Use at least 10 characters with uppercase, lowercase and a number.';
  elseif($new!==$confirm)$error='New passwords do not match.';
  elseif(password_verify($new,$row['password']))$error='Choose a different password.';
  else{safeRun($pdo,'UPDATE users SET password=?,must_change_password=0 WHERE id=?',[password_hash($new,PASSWORD_BCRYPT),$_SESSION['user_id']]);$_SESSION['must_change_password']=0;auditLog($pdo,(int)$_SESSION['user_id'],'change_password','Password changed');$role=$_SESSION['role'];if($role==='lecturer'&&empty(currentLecturerRoles($pdo)))redirect(BASE_URL.'/dashboard/pending-role.php');redirect(BASE_URL.'/dashboard/'.$role.'/index.php');}
 }
}
?>
