 alert-danger small"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrfField() ?><label class="form-label">Current password</label><input required type="password" name="current_password" class="form-control mb-3"><label class="form-label">New password</label><input required minlength="10" type="password" name="new_password" class="form-control mb-2"><div class="small text-muted mb-3">At least 10 characters with uppercase, lowercase and a number.</div><label class="form-label">Confirm new password</label><input required minlength="10" type="password" name="confirm_password" class="form-control mb-3"><button class="btn-save">Save password</button></form></div></body></html>
